{
  "name": "opencode-github",
  "version": "0.1.4",
  "description": "GitHub pull requests inside the OpenCode v2 TUI",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vestia-dev/opencode-github.git"
  },
  "homepage": "https://github.com/vestia-dev/opencode-github#readme",
  "bugs": {
    "url": "https://github.com/vestia-dev/opencode-github/issues"
  },
  "keywords": [
    "opencode",
    "github",
    "pull-request",
    "tui"
  ],
  "packageManager": "npm@11.11.0",
  "engines": {
    "node": ">=22.12.0"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    }
  },
  "scripts": {
    "clean": "node -e \"require('node:fs').rmSync('dist', { recursive: true, force: true })\"",
    "build": "npm run clean && tsc -p tsconfig.build.json",
    "dev": "tsc -p tsconfig.build.json --watch --preserveWatchOutput",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "typecheck": "tsc --noEmit",
    "check": "npm run format:check && npm run typecheck && npm run build",
    "prepack": "npm run check"
  },
  "dependencies": {
    "@opencode-ai/plugin": "0.0.0-next-16741",
    "@opencode-ai/theme": "0.0.0-next-16741",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "diff": "9.0.0",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "0.0.0-next-16741",
    "@opencode-ai/theme": "0.0.0-next-16741",
    "@opentui/core": "0.4.5",
    "@opentui/keymap": "0.4.5",
    "@opentui/solid": "0.4.5",
    "@types/node": "24.3.0",
    "prettier": "3.6.2",
    "solid-js": "1.9.12",
    "typescript": "5.9.2"
  }
}
